R=/scratch/jjyeung/orch_n30
date -u +%TZ; free -g | sed -n 2p; cat /proc/loadavg
mkdir -p $R/sb_ktfix2/prompts $R/sb_ktfix2/out; echo  | base64 -d > $R/sb_ktfix2/prompts/sb_ktfix2.md
{ cat $R/sb_queue/queue.txt; echo sb_ktfix2; } > $R/sb_queue/q.tmp; cat $R/sb_queue/q.tmp > $R/sb_queue/queue.txt; echo Q: $(cat $R/sb_queue/queue.txt | tr "\n" " ")
for w in sb_k1012 sb_rlfix4; do mkdir -p $R/$w; cp $R/sb_cursor_probe/AGENTS.md $R/$w/AGENTS.md; done
echo  | base64 -d > $R/sb_k1012/PROMPT.md; echo  | base64 -d > $R/sb_rlfix4/PROMPT.md
for w in sb_k1012 sb_rlfix4; do cd $R/$w && tmux new-session -d -s $w "OMP_NUM_THREADS=8 MKL_NUM_THREADS=8 OPENBLAS_NUM_THREADS=8 nice -n 10 timeout 5400 agent -p -f --sandbox disabled --trust --model claude-opus-5-5-xhigh 'Read PROMPT.md in this folder and carry out the task it describes, completely.' > cursor.log 2>&1"; sleep 3; done
tmux ls -F "#{session_name}" | grep "^sb_" | tr "\n" " "; echo
